const payload = $input.first().json;
const data = payload.data || payload;

if (!data || !data.key) {
  return [];
}

// 1. Discard bot's outbound messages
if (data.key.fromMe === true) {
  return [];
}

// 2. Discard WhatsApp groups
const remoteJid = data.key.remoteJid || '';
if (remoteJid.includes('@g.us') || remoteJid.includes('@broadcast')) {
  return [];
}

// 3. Extract clean phone
const cleanPhone = remoteJid.replace('@s.whatsapp.net', '').replace(/[^0-9]/g, '');

// 4. Extract message text
const messageObj = data.message || {};
let messageText = '';
if (messageObj.conversation) {
  messageText = messageObj.conversation;
} else if (messageObj.extendedTextMessage && messageObj.extendedTextMessage.text) {
  messageText = messageObj.extendedTextMessage.text;
}

messageText = (messageText || '').trim();
if (!messageText) {
  return [];
}

// 5. Detect Tamil script via Unicode range U+0B80 - U+0BFF
const isTamil = /[\u0B80-\u0BFF]/.test(messageText);

return [{
  json: {
    clean_phone: cleanPhone,
    remoteJid: remoteJid,
    senderName: data.pushName || 'WhatsApp Customer',
    originalText: messageText,
    isTamil: isTamil,
    messageId: data.key.id
  }
}];

const originalText = $('Detect Tamil Characters').item.json.originalText;
let englishText = '';

// Check if GCP Translate responded successfully
if ($input.first().json && $input.first().json.data && $input.first().json.data.translations) {
  englishText = $input.first().json.data.translations[0].translatedText;
} else {
  // Graceful fallback for test/dev mode if GCP key not provided
  englishText = `[AI Translation]: ${originalText}`;
}

const formattedContent = `[Original Tamil]:\n${originalText}\n\n[AI English Translation]:\n${englishText}`;

return [{
  json: {
    clean_phone: $('Detect Tamil Characters').item.json.clean_phone,
    senderName: $('Detect Tamil Characters').item.json.senderName,
    formattedContent: formattedContent,
    originalText: originalText,
    englishText: englishText
  }
}];

const originalText = $('Detect Tamil Characters').item.json.originalText;
const formattedContent = `[English Message]:\n${originalText}`;

return [{
  json: {
    clean_phone: $('Detect Tamil Characters').item.json.clean_phone,
    senderName: $('Detect Tamil Characters').item.json.senderName,
    formattedContent: formattedContent,
    originalText: originalText,
    englishText: originalText
  }
}];
